import scala.collection.mutable

final class Lru[K, V](cap: Int) {
  private val m = mutable.LinkedHashMap.empty[K, V]
  def get(k: K): Option[V] = m.remove(k).map { v => m.update(k, v); v }   // touch
  def put(k: K, v: V): Unit = {
    m.remove(k)
    if (m.size >= cap) m.remove(m.head._1)     // evict oldest
    m.update(k, v)
  }
}
